create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text,role text not null default 'viewer' check(role in('admin','practitioner','reception','inventory','viewer')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.clinic_state(id uuid primary key,data jsonb not null default '{"patients":[],"appointments":[],"encounters":[],"inventory":[],"activity":[]}'::jsonb,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key,occurred_at timestamptz not null default now(),user_id uuid references auth.users(id),action text not null,entity text not null,entity_id text,metadata jsonb not null default '{}'::jsonb);
create or replace function public.current_user_role() returns text language sql stable security definer set search_path=public as $$select coalesce((select role from public.profiles where id=auth.uid()),'viewer');$$;
revoke all on function public.current_user_role() from public;grant execute on function public.current_user_role() to authenticated;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$declare assigned_role text;begin if not exists(select 1 from public.profiles) then assigned_role:='admin';else assigned_role:='viewer';end if;insert into public.profiles(id,email,full_name,role) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name',new.email),assigned_role) on conflict(id) do update set email=excluded.email,full_name=excluded.full_name,updated_at=now();return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert or update of email,raw_user_meta_data on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security;alter table public.clinic_state enable row level security;alter table public.audit_logs enable row level security;
drop policy if exists profiles_read_self_or_admin on public.profiles;create policy profiles_read_self_or_admin on public.profiles for select to authenticated using(id=auth.uid() or public.current_user_role()='admin');
drop policy if exists profiles_admin_update on public.profiles;create policy profiles_admin_update on public.profiles for update to authenticated using(public.current_user_role()='admin') with check(public.current_user_role()='admin');
drop policy if exists clinic_state_read_staff on public.clinic_state;create policy clinic_state_read_staff on public.clinic_state for select to authenticated using(public.current_user_role() in('admin','practitioner','reception','inventory','viewer'));
drop policy if exists clinic_state_insert_staff on public.clinic_state;create policy clinic_state_insert_staff on public.clinic_state for insert to authenticated with check(public.current_user_role() in('admin','practitioner','reception','inventory'));
drop policy if exists clinic_state_update_staff on public.clinic_state;create policy clinic_state_update_staff on public.clinic_state for update to authenticated using(public.current_user_role() in('admin','practitioner','reception','inventory')) with check(public.current_user_role() in('admin','practitioner','reception','inventory'));
drop policy if exists clinic_state_delete_admin on public.clinic_state;create policy clinic_state_delete_admin on public.clinic_state for delete to authenticated using(public.current_user_role()='admin');
drop policy if exists audit_insert_authenticated on public.audit_logs;create policy audit_insert_authenticated on public.audit_logs for insert to authenticated with check(user_id=auth.uid());
drop policy if exists audit_read_admin on public.audit_logs;create policy audit_read_admin on public.audit_logs for select to authenticated using(public.current_user_role()='admin');
insert into public.profiles(id,email,full_name,role) select u.id,u.email,coalesce(u.raw_user_meta_data->>'full_name',u.raw_user_meta_data->>'name',u.email),case when row_number() over(order by u.created_at)=1 then 'admin' else 'viewer' end from auth.users u on conflict(id) do nothing;
insert into public.clinic_state(id) values('00000000-0000-0000-0000-000000000001') on conflict(id) do nothing;
